<style>
.qard-page{max-width:1250px;margin:auto;color:#203d35}.qard-page h1{font-size:27px}.qard-page h2{font-size:19px;margin:0 0 16px}.qard-page .qcard{background:#fff;border:1px solid #dce6e1;border-radius:12px;padding:22px;margin:18px 0}.qard-page .qgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(230px,1fr));gap:18px}.qard-page label{display:block;font-weight:600;margin-bottom:6px}.qard-page input,.qard-page select,.qard-page textarea{width:100%;padding:10px;border:1px solid #cbd9d2;border-radius:7px;background:#fff}.qard-page textarea{min-height:95px}.qard-page .qbtn{display:inline-block;padding:9px 15px;border-radius:7px;background:#194c3d;color:#fff;border:0;text-decoration:none;cursor:pointer}.qard-page .qbtn.secondary{background:#edf3ef;color:#194c3d}.qard-page .qbtn.danger{background:#963e38}.qard-page .qactions{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin-top:15px}.qard-page .qmuted{color:#63766e}.qard-page .qbadge{background:#edf3ef;border-radius:18px;padding:5px 10px;display:inline-block}.qard-page .qtable{overflow-x:auto}.qard-page table{width:100%;border-collapse:collapse}.qard-page th,.qard-page td{text-align:left;padding:11px;border-bottom:1px solid #e2eae6;vertical-align:top}.qard-page .qalert{padding:15px;border-radius:8px;background:#fff1d6;margin:15px 0}.qard-page .qsuccess{background:#e8f5eb}.qard-page .qvalue{font-size:24px;font-weight:700}.qard-page .qnote{white-space:pre-wrap;overflow-wrap:anywhere}.qard-page details{margin:12px 0}.qard-page small{display:block}.qard-page form{margin-bottom:0}
</style>
